package cli

import (
	"context"
	"fmt"
	"sort"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

// queryEnv is the read-side scaffolding shared by tour/impact/examples/hotspots.
// It loads the fused graph plus the manifest once per command invocation and
// exposes precomputed lookups (node-by-ID, contains-children, touched_in
// counts).
type queryEnv struct {
	root     string
	store    *graph.Store
	manifest *graph.Manifest
	fused    *graph.Slice

	byID         map[string]*graph.Node
	containsFrom map[string][]*graph.Node // parent -> direct children via EdgeContains
	touchedCount map[string]int           // file/ghost ID -> distinct cp count
	touchedCps   map[string][]string      // file/ghost ID -> cp node IDs (chronological)
}

// loadQueryEnv returns a fully-populated queryEnv. Returns a "no cache" sentinel
// error when the build hasn't run; commands surface that to the user with a
// hint to run build, then exit cleanly.
func loadQueryEnv(ctx context.Context) (*queryEnv, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve repo root: %w", err)
	}
	store := graph.NewStore(root)
	if !store.Exists() {
		return nil, errNoUnderstandCache
	}
	manifest, err := store.ReadManifest()
	if err != nil {
		return nil, fmt.Errorf("read manifest: %w", err)
	}
	fused, err := store.FusedGraph()
	if err != nil {
		return nil, fmt.Errorf("read fused graph: %w", err)
	}

	q := &queryEnv{
		root:         root,
		store:        store,
		manifest:     manifest,
		fused:        fused,
		byID:         make(map[string]*graph.Node, len(fused.Nodes)),
		containsFrom: make(map[string][]*graph.Node),
		touchedCount: map[string]int{},
		touchedCps:   map[string][]string{},
	}
	for i := range fused.Nodes {
		q.byID[fused.Nodes[i].ID] = &fused.Nodes[i]
	}
	for _, e := range fused.Edges {
		if e.Type == graph.EdgeContains {
			if child, ok := q.byID[e.To]; ok {
				q.containsFrom[e.From] = append(q.containsFrom[e.From], child)
			}
		}
		if e.Type == graph.EdgeTouchedIn {
			q.touchedCount[e.To]++
			q.touchedCps[e.To] = append(q.touchedCps[e.To], e.From)
		}
	}
	// Stable child ordering for tour/explain.
	for k := range q.containsFrom {
		children := q.containsFrom[k]
		sort.Slice(children, func(i, j int) bool { return children[i].ID < children[j].ID })
		q.containsFrom[k] = children
	}
	return q, nil
}

// errNoUnderstandCache is returned by loadQueryEnv when the build has not run.
// Commands check for this sentinel and emit a friendly hint rather than the
// generic error. Defined as a single package-level value so callers can use
// errors.Is.
var errNoUnderstandCache = noUnderstandCacheError{}

type noUnderstandCacheError struct{}

func (noUnderstandCacheError) Error() string {
	return "no understand cache yet — run `entire understand build`"
}

// descendantFiles walks contains-edges from start and returns every file or
// ghost node reachable. Order is preserved (BFS). Used by tour and impact to
// build subtree views without rewalking the graph each time.
func (q *queryEnv) descendantFiles(start string) []*graph.Node {
	out := []*graph.Node{}
	if start == "" {
		return out
	}
	seen := map[string]bool{start: true}
	queue := []string{start}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		for _, child := range q.containsFrom[cur] {
			if seen[child.ID] {
				continue
			}
			seen[child.ID] = true
			if child.Type == graph.NodeFile {
				out = append(out, child)
			}
			queue = append(queue, child.ID)
		}
	}
	return out
}

// resolveAreaNode picks the right starting node for tour/impact. Resolution is
// the same as explain's resolver, defined separately so the helper file
// doesn't depend on understand_explain.go beyond what's already exported.
func (q *queryEnv) resolveAreaNode(target string) (*graph.Node, error) {
	return resolveExplainNode(q.fused, target, q.root)
}

// recentCheckpoint returns the highest-CreatedAt cp node among those touching
// `nodeID`, or nil when none exist. Useful for tour stop annotations.
func (q *queryEnv) recentCheckpoint(nodeID string) *graph.Node {
	cps := q.touchedCps[nodeID]
	if len(cps) == 0 {
		return nil
	}
	var best *graph.Node
	bestAt := ""
	for _, cpID := range cps {
		cp := q.byID[cpID]
		if cp == nil {
			continue
		}
		at, _ := cp.Attrs["created_at"].(string)
		if best == nil || at > bestAt {
			best = cp
			bestAt = at
		}
	}
	return best
}

