package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os/exec"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/spf13/cobra"
)

// newUnderstandPrCmd builds `entire understand pr <id|--base ... --head ...>`.
//
// Numeric PR lookup uses the locally installed `gh` CLI when present. If `gh`
// is missing or unauthenticated we fall back to comparing two refs (--base /
// --head) or a revset (--rev). Credentials are never read or written by this
// command — auth is owned entirely by the user's `gh` install.
func newUnderstandPrCmd() *cobra.Command {
	var (
		base    string
		head    string
		revset  string
		jsonOut bool
		maxFiles int
	)

	cmd := &cobra.Command{
		Use:   "pr [id]",
		Short: "Reviewer pre-flight grounded in graph + checkpoint history",
		Long: `Render a review brief for a pull request.

Sources, in priority order:
  1. Numeric PR id via 'gh pr view --json baseRefName,headRefName,files'
     (requires gh on PATH; never falls back to embedded auth)
  2. --base <ref> --head <ref> using local 'git diff'
  3. --rev <revset> using local 'git diff'

Examples:
  entire understand pr 1234
  entire understand pr --base main --head HEAD
  entire understand pr --rev origin/main..HEAD`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			id := ""
			if len(args) == 1 {
				id = args[0]
			}
			return runUnderstandPr(cmd.Context(), cmd.OutOrStdout(), prOptions{
				ID:       id,
				Base:     base,
				Head:     head,
				Revset:   revset,
				JSONOut:  jsonOut,
				MaxFiles: maxFiles,
			})
		},
	}
	cmd.Flags().StringVar(&base, "base", "", "Base ref for diff fallback (used when no PR id)")
	cmd.Flags().StringVar(&head, "head", "HEAD", "Head ref for diff fallback")
	cmd.Flags().StringVar(&revset, "rev", "", "Revset for diff fallback (e.g. origin/main..HEAD)")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of markdown")
	cmd.Flags().IntVar(&maxFiles, "max-files", 50, "Maximum number of touched files to annotate")
	return cmd
}

type prOptions struct {
	ID       string
	Base     string
	Head     string
	Revset   string
	JSONOut  bool
	MaxFiles int
}

type prTouchedFile struct {
	Path           string `json:"path"`
	Status         string `json:"status,omitempty"` // "added", "modified", "removed", "renamed"
	NodeID         string `json:"node_id,omitempty"`
	LastCheckpoint string `json:"last_checkpoint,omitempty"`
	LastAt         string `json:"last_at,omitempty"`
	LastAgent      string `json:"last_agent,omitempty"`
	HotspotScore   float64 `json:"hotspot_score,omitempty"`
}

type prReport struct {
	Source   string          `json:"source"` // "gh" | "diff" | "revset"
	ID       string          `json:"id,omitempty"`
	Base     string          `json:"base,omitempty"`
	Head     string          `json:"head,omitempty"`
	Revset   string          `json:"revset,omitempty"`
	Files    []prTouchedFile `json:"files"`
	Reason   string          `json:"reason,omitempty"`
	NoCache  bool            `json:"no_cache,omitempty"`
}

func runUnderstandPr(ctx context.Context, w io.Writer, opts prOptions) error {
	q, err := loadQueryEnv(ctx)
	if err != nil {
		if errors.Is(err, errNoUnderstandCache) {
			report := prReport{NoCache: true, Reason: err.Error()}
			return emitPr(w, report, opts.JSONOut)
		}
		return err
	}
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("resolve repo root: %w", err)
	}

	report := prReport{}
	var paths []touchedFileRaw

	switch {
	case opts.ID != "":
		paths, err = ghTouchedFiles(ctx, opts.ID)
		if err != nil {
			report.Reason = fmt.Sprintf("gh lookup failed (%s); pass --base / --head to use local diff", err.Error())
			return emitPr(w, report, opts.JSONOut)
		}
		report.Source = "gh"
		report.ID = opts.ID
	case opts.Revset != "":
		paths, err = gitTouchedFiles(ctx, repoRoot, []string{opts.Revset})
		if err != nil {
			return fmt.Errorf("git diff %s: %w", opts.Revset, err)
		}
		report.Source = "revset"
		report.Revset = opts.Revset
	case opts.Base != "":
		args := []string{opts.Base + "..." + opts.Head}
		paths, err = gitTouchedFiles(ctx, repoRoot, args)
		if err != nil {
			return fmt.Errorf("git diff %s..%s: %w", opts.Base, opts.Head, err)
		}
		report.Source = "diff"
		report.Base = opts.Base
		report.Head = opts.Head
	default:
		return errors.New("understand pr: provide a PR id, or --base/--head, or --rev")
	}

	if opts.MaxFiles > 0 && len(paths) > opts.MaxFiles {
		paths = paths[:opts.MaxFiles]
	}
	for _, p := range paths {
		f := prTouchedFile{Path: p.Path, Status: p.Status}
		nodeID := "file:" + p.Path
		if _, ok := q.byID[nodeID]; !ok {
			nodeID = "ghost:" + p.Path
		}
		if n, ok := q.byID[nodeID]; ok {
			f.NodeID = n.ID
			if cp := q.recentCheckpoint(n.ID); cp != nil {
				f.LastCheckpoint = cp.Name
				if at, ok := cp.Attrs["created_at"].(string); ok {
					f.LastAt = at
				}
				if ag, ok := cp.Attrs["agent"].(string); ok {
					f.LastAgent = ag
				}
			}
			f.HotspotScore = float64(q.touchedCount[n.ID])
		}
		report.Files = append(report.Files, f)
	}
	sort.SliceStable(report.Files, func(i, j int) bool {
		return report.Files[i].HotspotScore > report.Files[j].HotspotScore
	})

	return emitPr(w, report, opts.JSONOut)
}

type touchedFileRaw struct {
	Path   string
	Status string
}

// ghTouchedFiles invokes `gh pr view <id> --json files,baseRefName,headRefName`.
// gh's JSON output for `files` is an array of {path, additions, deletions}
// objects; we map each to a path with status="modified" because gh does not
// distinguish renames in this view.
func ghTouchedFiles(ctx context.Context, prID string) ([]touchedFileRaw, error) {
	if _, err := exec.LookPath("gh"); err != nil {
		return nil, fmt.Errorf("gh not on PATH: %w", err)
	}
	cmd := exec.CommandContext(ctx, "gh", "pr", "view", prID, "--json", "files")
	out, err := cmd.Output()
	if err != nil {
		var ex *exec.ExitError
		if errors.As(err, &ex) {
			return nil, fmt.Errorf("gh pr view %s exit %d: %s", prID, ex.ExitCode(), strings.TrimSpace(string(ex.Stderr)))
		}
		return nil, fmt.Errorf("gh pr view %s: %w", prID, err)
	}
	var parsed struct {
		Files []struct {
			Path string `json:"path"`
		} `json:"files"`
	}
	if err := json.Unmarshal(out, &parsed); err != nil {
		return nil, fmt.Errorf("parse gh json: %w", err)
	}
	files := make([]touchedFileRaw, 0, len(parsed.Files))
	for _, f := range parsed.Files {
		files = append(files, touchedFileRaw{Path: f.Path, Status: "modified"})
	}
	return files, nil
}

// gitTouchedFiles runs `git diff --name-status` for the given args and returns
// the touched paths annotated with their porcelain status code (A/M/D/R...).
func gitTouchedFiles(ctx context.Context, repoRoot string, diffArgs []string) ([]touchedFileRaw, error) {
	args := append([]string{"diff", "--name-status"}, diffArgs...)
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = repoRoot
	out, err := cmd.Output()
	if err != nil {
		var ex *exec.ExitError
		if errors.As(err, &ex) {
			return nil, fmt.Errorf("git diff exit %d: %s", ex.ExitCode(), strings.TrimSpace(string(ex.Stderr)))
		}
		return nil, fmt.Errorf("git diff: %w", err)
	}
	files := []touchedFileRaw{}
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		status := translateGitStatus(fields[0])
		// Renames have format `R<score> old new`; pick the new path.
		path := fields[len(fields)-1]
		files = append(files, touchedFileRaw{Path: path, Status: status})
	}
	return files, nil
}

func translateGitStatus(code string) string {
	if code == "" {
		return ""
	}
	switch code[0] {
	case 'A':
		return "added"
	case 'D':
		return "removed"
	case 'M':
		return "modified"
	case 'R':
		return "renamed"
	case 'C':
		return "copied"
	default:
		return strings.ToLower(code)
	}
}

func emitPr(w io.Writer, r prReport, jsonOut bool) error {
	if jsonOut {
		data, err := jsonutil.MarshalIndentWithNewline(r, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal pr: %w", err)
		}
		if _, err := w.Write(data); err != nil {
			return fmt.Errorf("write pr JSON: %w", err)
		}
		return nil
	}
	if r.NoCache {
		fmt.Fprintln(w, r.Reason)
		return nil
	}
	if r.Reason != "" {
		fmt.Fprintln(w, r.Reason)
		return nil
	}
	switch r.Source {
	case "gh":
		fmt.Fprintf(w, "# PR review: #%s\n\n", r.ID)
	case "diff":
		fmt.Fprintf(w, "# Diff review: %s..%s\n\n", r.Base, r.Head)
	case "revset":
		fmt.Fprintf(w, "# Revset review: %s\n\n", r.Revset)
	}
	if len(r.Files) == 0 {
		fmt.Fprintln(w, "_No touched files in the requested range._")
		return nil
	}
	for _, f := range r.Files {
		status := f.Status
		if status == "" {
			status = "modified"
		}
		fmt.Fprintf(w, "- **%s** _(%s)_", f.Path, status)
		if f.HotspotScore > 0 {
			fmt.Fprintf(w, " — touched in %d prior checkpoint(s)", int(f.HotspotScore))
		}
		if f.LastCheckpoint != "" {
			fmt.Fprintf(w, "; last in `%s`", f.LastCheckpoint)
			if f.LastAt != "" {
				fmt.Fprintf(w, " at %s", f.LastAt)
			}
			if f.LastAgent != "" {
				fmt.Fprintf(w, " by %s", f.LastAgent)
			}
		}
		fmt.Fprintln(w)
	}
	return nil
}

