//go:build integration

package integration

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestUnderstand_BuildStatusExplain_EndToEnd drives the new
// `entire understand` group through the real CLI binary. It seeds a small
// repo with two source files plus a README, runs build → status → explain,
// and asserts the surfaces line up: status reports the cache, structural
// nodes appear, and explain returns the seeded file with a clean shape.
//
// Semantic stage is skipped via --no-semantic so the test never reaches
// out to a real provider CLI.
func TestUnderstand_BuildStatusExplain_EndToEnd(t *testing.T) {
	t.Parallel()

	env := NewRepoWithCommit(t)
	env.WriteFile("cmd/main.go", "package main\n\nfunc main() {}\n")
	env.WriteFile("lib/util.go", "package lib\n\n// Hello returns hi.\nfunc Hello() string { return \"hi\" }\n")
	env.GitAdd("cmd/main.go")
	env.GitAdd("lib/util.go")
	env.GitCommit("seed: minimal repo")

	// 1. Build
	out := env.RunCLI("understand", "build", "--no-semantic")
	if !strings.Contains(out, "structural:") {
		t.Errorf("build output missing structural progress line:\n%s", out)
	}
	if !strings.Contains(out, "build complete") {
		t.Errorf("build output missing completion line:\n%s", out)
	}

	// Cache directory exists and contains the expected files.
	cacheDir := filepath.Join(env.RepoDir, ".entire", "understand")
	for _, name := range []string{"manifest.json", "structural.json", "history.json", "timeline.json"} {
		path := filepath.Join(cacheDir, name)
		if _, err := os.Stat(path); err != nil {
			t.Errorf("expected artifact %s missing: %v", name, err)
		}
	}

	// 2. Status (JSON form is the stable contract for downstream tools)
	statusOut := env.RunCLI("understand", "status", "--json")
	var status struct {
		Present  bool `json:"present"`
		Manifest struct {
			BuildID            string   `json:"build_id"`
			StructuralStatus   string   `json:"structural_status"`
			HistoryStatus      string   `json:"history_status"`
			SemanticStatus     string   `json:"semantic_status"`
			SupportedLanguages []string `json:"supported_languages"`
			NodeCount          int      `json:"node_count"`
		} `json:"manifest"`
	}
	if err := json.Unmarshal([]byte(statusOut), &status); err != nil {
		t.Fatalf("status JSON: %v\nraw=%s", err, statusOut)
	}
	if !status.Present {
		t.Fatalf("status.Present=false; want true")
	}
	if status.Manifest.StructuralStatus != "ok" {
		t.Errorf("structural status=%q; want ok", status.Manifest.StructuralStatus)
	}
	if status.Manifest.SemanticStatus != "skipped" {
		t.Errorf("semantic status=%q; want skipped", status.Manifest.SemanticStatus)
	}
	hasGo := false
	for _, l := range status.Manifest.SupportedLanguages {
		if l == "go" {
			hasGo = true
		}
	}
	if !hasGo {
		t.Errorf("SupportedLanguages=%v; want go", status.Manifest.SupportedLanguages)
	}
	if status.Manifest.NodeCount == 0 {
		t.Errorf("NodeCount=0; want >0")
	}

	// 3. Explain a known file
	explainOut := env.RunCLI("understand", "explain", "cmd/main.go", "--json")
	var explain struct {
		Node *struct {
			ID       string `json:"id"`
			Type     string `json:"type"`
			Path     string `json:"path"`
			Language string `json:"language"`
		} `json:"node"`
		Children []struct {
			Type       string `json:"type"`
			SymbolKind string `json:"symbol_kind"`
			Name       string `json:"name"`
		} `json:"children"`
	}
	if err := json.Unmarshal([]byte(explainOut), &explain); err != nil {
		t.Fatalf("explain JSON: %v\nraw=%s", err, explainOut)
	}
	if explain.Node == nil {
		t.Fatalf("explain.Node nil")
	}
	if explain.Node.ID != "file:cmd/main.go" {
		t.Errorf("Node.ID=%q; want file:cmd/main.go", explain.Node.ID)
	}
	if explain.Node.Type != "file" {
		t.Errorf("Node.Type=%q; want file", explain.Node.Type)
	}
	if explain.Node.Language != "go" {
		t.Errorf("Node.Language=%q; want go", explain.Node.Language)
	}
	// Symbol child for `main` should be present.
	foundMain := false
	for _, c := range explain.Children {
		if c.Type == "symbol" && c.Name == "main" && c.SymbolKind == "function" {
			foundMain = true
		}
	}
	if !foundMain {
		t.Errorf("expected symbol child `main` in explain.children: %+v", explain.Children)
	}

	// 4. Hotspots and replay return clean JSON even with no checkpoints.
	hotspotsOut := env.RunCLI("understand", "hotspots", "--json")
	var hotspots struct {
		Hotspots []map[string]any `json:"hotspots"`
	}
	if err := json.Unmarshal([]byte(hotspotsOut), &hotspots); err != nil {
		t.Fatalf("hotspots JSON: %v\nraw=%s", err, hotspotsOut)
	}
	// No checkpoints branch in this repo, so hotspots is empty but the
	// command still emits a well-formed payload.
	if hotspots.Hotspots == nil {
		t.Errorf("hotspots payload missing 'hotspots' key:\n%s", hotspotsOut)
	}

	replayOut := env.RunCLI("understand", "replay", "--json")
	var replay struct {
		Events []map[string]any `json:"events"`
	}
	if err := json.Unmarshal([]byte(replayOut), &replay); err != nil {
		t.Fatalf("replay JSON: %v\nraw=%s", err, replayOut)
	}
	if replay.Events == nil {
		t.Errorf("replay payload missing 'events' key:\n%s", replayOut)
	}

	// 5. Dashboard --print emits the token but does not bind a port.
	dashOut := env.RunCLI("understand", "dashboard", "--print")
	if !strings.Contains(dashOut, "would-launch:") || !strings.Contains(dashOut, "token=") {
		t.Errorf("dashboard --print missing expected banner:\n%s", dashOut)
	}
}

